 async function create(e:React.FormEvent){e.preventDefault();setBusy(true);try{const extra=tab==='WHATS_NEW'?{release_date:releaseDate,major_update:majorUpdate}:{};const translations:any={};if(titleEn.trim())translations.en={title:titleEn,body:tab==='TIP'?{steps:tipsEn.map(st=>({...st,text:persistImages(st.text)}))}:{html:persistImages(bodyEn),...extra}};if(titleFr.trim())translations.fr={title:titleFr,body:tab==='TIP'?{steps:tipsFr.map(st=>({...st,text:persistImages(st.text)}))}:{html:persistImages(bodyFr),...extra}};const payload={content_type:tab,scope,tenant_id:scope==='TENANT'?tenantId:null,category:tab==='TIP'?category:null,target_bpal_version:targetVersion||null,visible_from:visibleFrom?new Date(visibleFrom).toISOString():null,visible_to:visibleTo?new Date(visibleTo).toISOString():null,translations};let savedId=editingId;if(editingId)await api(`/admin/cms/content/${editingId}`,{method:'PUT',body:JSON.stringify({category:payload.category,target_bpal_version:payload.target_bpal_version,visible_from:payload.visible_from,visible_to:payload.visible_to,translations})});else {const created=await api('/admin/cms/content',{method:'POST',body:JSON.stringify(payload)});savedId=created.content_id;}for(const id of mediaIds){if(savedId)await api(`/admin/cms/content/${savedId}/media/${id}`,{method:'POST'});}setMediaIds([]);setShowEditor(false);setEditingId(null);setTitleEn('');setTitleFr('');setBodyEn('');setBodyFr('');setTipsEn([blankStep()]);setTipsFr([blankStep()]);setTargetVersion('');setReleaseDate('');setVisibleFrom('');setVisibleTo('');setMajorUpdate(false);await load();setNotice(editingId?'Draft updated successfully.':'Draft created successfully.')}catch(e){setNotice((e as Error).message)}finally{setBusy(false)}}
 function edit(item:Item){setEditorView('EDIT');setEditingId(item.content_id);setTab(item.content_type as 'TIP'|'WHATS_NEW');setScope(item.scope);setTenantId(item.tenant_id||'');setCategory(item.category||'');setTargetVersion((item as any).target_bpal_version||'');setVisibleFrom((item as any).visible_from?new Date((item as any).visible_from).toISOString().slice(0,16):'');setVisibleTo((item as any).visible_to?new Date((item as any).visible_to).toISOString().slice(0,16):'');setReleaseDate(((item.translations?.en?.body as any)?.release_date)||'');setMajorUpdate(Boolean((item.translations?.en?.body as any)?.major_update));setTitleEn(item.translations?.en?.title||'');setTitleFr(item.translations?.fr?.title||'');const en=item.translations?.en?.body as any;const fr=item.translations?.fr?.body as any;setMediaIds([]);setBodyEn(en?.html||'');setBodyFr(fr?.html||'');setTipsEn(stepsFromBody(en));setTipsFr(stepsFromBody(fr));setShowEditor(true);void hydrateStepImages([...stepsFromBody(en),...stepsFromBody(fr)]);void Promise.all([hydrateImages(en?.html||''),hydrateImages(fr?.html||'')]).then(([a,b])=>{setBodyEn(a);setBodyFr(b)}).catch(e=>setNotice(String(e)))}
